  PORT_CODE                VARCHAR2(6) NOT NULL,
  BOE_TYPE                 VARCHAR2(1) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  IEC_NO                   VARCHAR2(10) NOT NULL,
  AD_CODE                  VARCHAR2(14),
  INV_MGMT_NO              VARCHAR2(16),
  PRODUCT_CODE             VARCHAR2(2),
  CCY                      VARCHAR2(3) NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  IGST_RATE                NUMBER(5,2),
  IGST_AMT                 NUMBER(18,2),
  TOTAL_AMT                NUMBER(18,2) NOT NULL,
  SETTLED_AMT              NUMBER(18,2) NOT NULL,
  OUTSTANDING_AMT          NUMBER(18,2) NOT NULL,
  SHIPMENT_DT              DATE,
  SETTLE_DUE_DT            DATE,
  SOURCE                   VARCHAR2(1) NOT NULL,
  REG_DT                   DATE NOT NULL,
