COMMENT ON TABLE TB_FX_OBLIGATION IS '기한관리(Obligation)';
COMMENT ON COLUMN TB_FX_OBLIGATION.OBLIG_ID IS '기한ID';
COMMENT ON COLUMN TB_FX_OBLIGATION.OBLIG_TYPE IS '기한유형 - CODE:OBLIG_TYPE';
COMMENT ON COLUMN TB_FX_OBLIGATION.SRC_TABLE IS '원천테이블';
COMMENT ON COLUMN TB_FX_OBLIGATION.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_FX_OBLIGATION.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_FX_OBLIGATION.BASE_DT IS '기산일';
COMMENT ON COLUMN TB_FX_OBLIGATION.PARAM_ID IS '적용 파라미터 - 기한 산출 근거 추적';
COMMENT ON COLUMN TB_FX_OBLIGATION.PARAM_VALUE IS '적용값(스냅샷) - 규정 변경 후에도 당시 기준 재현';
COMMENT ON COLUMN TB_FX_OBLIGATION.DUE_DT IS '기한';
COMMENT ON COLUMN TB_FX_OBLIGATION.EXT_DUE_DT IS '연장기한';
COMMENT ON COLUMN TB_FX_OBLIGATION.EXT_APPROVAL_REF IS '연장 승인근거 - AD 승인/RBI 승인';
COMMENT ON COLUMN TB_FX_OBLIGATION.TARGET_AMT IS '이행대상액';
COMMENT ON COLUMN TB_FX_OBLIGATION.FULFILLED_AMT IS '이행액';
COMMENT ON COLUMN TB_FX_OBLIGATION.OBLIG_STS IS '상태 - CODE:OBLIG_STATUS (일배치 갱신)';
COMMENT ON COLUMN TB_FX_OBLIGATION.NEXT_ALERT_DT IS '다음 알림일';
COMMENT ON COLUMN TB_FX_OBLIGATION.FOLLOWUP_CNT IS '독촉횟수';
COMMENT ON COLUMN TB_FX_OBLIGATION.LAST_FOLLOWUP_DT IS '최종독촉일';
COMMENT ON COLUMN TB_FX_OBLIGATION.FULFILLED_DT IS '이행일';
COMMENT ON COLUMN TB_FX_OBLIGATION.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_OBLIGATION.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_OBLIGATION.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_OBLIGATION.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_OBLIGATION.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_FX_OBLIGATION_1 ON TB_FX_OBLIGATION (OBLIG_STS,DUE_DT);
CREATE INDEX IX_FX_OBLIGATION_2 ON TB_FX_OBLIGATION (SRC_TABLE,SRC_KEY);
CREATE INDEX IX_FX_OBLIGATION_3 ON TB_FX_OBLIGATION (CUST_NO);

-- 규정 파라미터 : 규정 수치 이력관리(유효기간). 규칙엔진은 거래 기준일의 유효 파라미터 사용.
CREATE TABLE TB_FX_PARAM (
