COMMENT ON COLUMN TB_FX_PARAM.PARAM_ID IS '파라미터ID';
COMMENT ON COLUMN TB_FX_PARAM.EFF_FROM_DT IS '적용시작일';
COMMENT ON COLUMN TB_FX_PARAM.EFF_TO_DT IS '적용종료일 - 기본 9999-12-31';
