COMMENT ON COLUMN TB_FX_PARAM.REG_SOURCE IS '근거규정';
COMMENT ON COLUMN TB_FX_PARAM.BASIS_DT_TYPE IS '기준일 유형 - TRX_DT/SHIP_DT/LEO_DT - 어떤 일자로 유효값을 고를지';
COMMENT ON COLUMN TB_FX_PARAM.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_PARAM.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_PARAM.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_PARAM.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_PARAM.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- Purpose Code 마스터 : RBI 갱신 시 일괄적재. OTHRS로 미등록 코드 임시 처리.
CREATE TABLE TB_CD_PURPOSE (
