COMMENT ON COLUMN TB_IF_IDPMS_ORM.AMT IS '금액';
COMMENT ON COLUMN TB_IF_IDPMS_ORM.PURPOSE_CODE IS 'Purpose - S0101/S0102 등';
COMMENT ON COLUMN TB_IF_IDPMS_ORM.PAY_TERMS IS '결제조건 - ADV/DIR';
