COMMENT ON COLUMN TB_CIMS_RETURN_DTL.SEQ IS '순번';
COMMENT ON COLUMN TB_CIMS_RETURN_DTL.SRC_TABLE IS '원천';
COMMENT ON COLUMN TB_CIMS_RETURN_DTL.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_CIMS_RETURN_DTL.ACTION IS '처리 - A/M/D';
COMMENT ON COLUMN TB_CIMS_RETURN_DTL.VAL_ERR IS '검증오류';

-- 환전 레그(부분환전) : 타발 1건을 여러 번·여러 환율로 나눠 환전/지급. INR 확정 환전도 레그 단위로 관리.
CREATE TABLE TB_FX_CONV_LEG (
  REMIT_REF_NO             VARCHAR2(16) NOT NULL,
