  INR_AMT                  NUMBER(18,2) NOT NULL,
  INR_FIXED_YN             VARCHAR2(1) NOT NULL,
  TARGET_INR_AMT           NUMBER(18,2),
  DEAL_REF_NO              VARCHAR2(16),
  DEST_MODE                VARCHAR2(6) NOT NULL,
  PAYOUT_ID                NUMBER(12),
  LEG_STS                  VARCHAR2(2) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_CONV_LEG PRIMARY KEY (REMIT_REF_NO, LEG_SEQ)
);
COMMENT ON TABLE TB_FX_CONV_LEG IS '환전 레그(부분환전)';
COMMENT ON COLUMN TB_FX_CONV_LEG.REMIT_REF_NO IS '송금참조번호';
COMMENT ON COLUMN TB_FX_CONV_LEG.LEG_SEQ IS '레그';
COMMENT ON COLUMN TB_FX_CONV_LEG.CONV_DT IS '환전일';
COMMENT ON COLUMN TB_FX_CONV_LEG.FCY_AMT IS '환전 외화 - Σ레그 FCY ≤ 수취 FCY';
COMMENT ON COLUMN TB_FX_CONV_LEG.FX_RATE IS '환율';
COMMENT ON COLUMN TB_FX_CONV_LEG.INR_AMT IS '환전 INR';
COMMENT ON COLUMN TB_FX_CONV_LEG.INR_FIXED_YN IS 'INR 확정여부 - Y: FCY = ROUNDUP(TARGET_INR/RATE,2)';
COMMENT ON COLUMN TB_FX_CONV_LEG.TARGET_INR_AMT IS '목표 INR';
COMMENT ON COLUMN TB_FX_CONV_LEG.DEAL_REF_NO IS '딜 Ref';
COMMENT ON COLUMN TB_FX_CONV_LEG.DEST_MODE IS '지급방식 - ACCT/NEFT/RTGS/SUSP(INR 보류)';
COMMENT ON COLUMN TB_FX_CONV_LEG.PAYOUT_ID IS '국내지급ID';
COMMENT ON COLUMN TB_FX_CONV_LEG.LEG_STS IS '상태 - 10예약/20환전/30지급/90취소';
COMMENT ON COLUMN TB_FX_CONV_LEG.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_CONV_LEG.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_CONV_LEG.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_CONV_LEG.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_CONV_LEG.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 미지급금(타발 보류) 원장 : 비계좌 수취인·지시대기·KYC대기 타발을 Remittance Payable(미지급금) GL에 보류. 통화별 잔액 관리.
CREATE TABLE TB_FX_SUSPENSE (
