-- 국내 INR 지급(NEFT/RTGS) : 타발·FDI·에스크로 지급금을 타행 계좌로 NEFT/RTGS 이체. UTR로 추적, 반송 시 미지급금 재보류.
CREATE TABLE TB_DOM_PAYOUT (
  PAYOUT_ID                NUMBER(12) NOT NULL,
  SRC_TABLE                VARCHAR2(30) NOT NULL,
  SRC_KEY                  VARCHAR2(40) NOT NULL,
  RAIL                     VARCHAR2(4) NOT NULL,
  BENE_NAME                VARCHAR2(140) NOT NULL,
  BENE_IFSC                VARCHAR2(11) NOT NULL,
  BENE_ACCT                VARCHAR2(34) NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  REMARKS                  VARCHAR2(140),
  UTR                      VARCHAR2(22),
  SENT_TS                  TIMESTAMP,
  PAYOUT_STS               VARCHAR2(4) NOT NULL,
  RTN_RSN                  VARCHAR2(100),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_DOM_PAYOUT PRIMARY KEY (PAYOUT_ID)
);
COMMENT ON TABLE TB_DOM_PAYOUT IS '국내 INR 지급(NEFT/RTGS)';
COMMENT ON COLUMN TB_DOM_PAYOUT.PAYOUT_ID IS '지급ID';
COMMENT ON COLUMN TB_DOM_PAYOUT.SRC_TABLE IS '원천 - TB_FX_CONV_LEG / TB_FDI_ESCROW_TXN / TB_FX_SUSPENSE';
COMMENT ON COLUMN TB_DOM_PAYOUT.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_DOM_PAYOUT.RAIL IS '이체망 - NEFT/RTGS (RTGS_MIN_INR 미만 RTGS 불가)';
COMMENT ON COLUMN TB_DOM_PAYOUT.BENE_NAME IS '수취인명';
COMMENT ON COLUMN TB_DOM_PAYOUT.BENE_IFSC IS 'IFSC - ^[A-Z]{4}0[A-Z0-9]{6}$';
COMMENT ON COLUMN TB_DOM_PAYOUT.BENE_ACCT IS '수취계좌';
COMMENT ON COLUMN TB_DOM_PAYOUT.AMT IS '금액(INR)';
COMMENT ON COLUMN TB_DOM_PAYOUT.REMARKS IS '이체 메시지 - FDI: FDI_REF_NO·투자자명 기재';
COMMENT ON COLUMN TB_DOM_PAYOUT.UTR IS 'UTR - SFMS 응답';
COMMENT ON COLUMN TB_DOM_PAYOUT.SENT_TS IS '송신일시';
COMMENT ON COLUMN TB_DOM_PAYOUT.PAYOUT_STS IS '상태 - NEW/SENT/CRDT(입금확인)/RTRN(반송)/FAIL';
COMMENT ON COLUMN TB_DOM_PAYOUT.RTN_RSN IS '반송사유 - 반송 시 TB_FX_SUSPENSE(RTN) 재생성';
COMMENT ON COLUMN TB_DOM_PAYOUT.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_DOM_PAYOUT.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_DOM_PAYOUT.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_DOM_PAYOUT.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_DOM_PAYOUT.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_DOM_PAYOUT_1 ON TB_DOM_PAYOUT (SRC_TABLE,SRC_KEY);
CREATE INDEX IX_DOM_PAYOUT_2 ON TB_DOM_PAYOUT (UTR);

-- FDI 에스크로 계좌 : FDI 관련 에스크로(지분양수도·이연대가·공개매수·인수대금). 무이자, 약정 조건 충족 시 지급/반환.
CREATE TABLE TB_FDI_ESCROW (
