  ESCROW_LIMIT             NUMBER(18,2) NOT NULL,
  BALANCE_AMT              NUMBER(18,2) NOT NULL,
  EXPIRY_DT                DATE NOT NULL,
  RELEASE_COND             VARCHAR2(500) NOT NULL,
  ESCROW_STS               VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
