  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FDI_ESCROW_TXN PRIMARY KEY (ESCROW_ACCT_NO, TXN_SEQ)
);
COMMENT ON TABLE TB_FDI_ESCROW_TXN IS 'FDI 에스크로 거래';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.ESCROW_ACCT_NO IS '에스크로 계좌';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.TXN_SEQ IS '순번';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.TXN_TYPE IS '유형 - DEPO예치/RLSE지급/RFND반환';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.TXN_DT IS '거래일';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.AMT IS '금액';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.REMIT_REF_NO IS '연결 송금 - DEPO=타발, RFND=당발(Product 07)';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.PAYOUT_ID IS '국내지급 - RLSE를 타행 지급 시';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.RELEASE_EVIDENCE IS '지급근거 - 양측 공동지시서/클로징 증빙';
