COMMENT ON COLUMN TB_FDI_ESCROW_TXN.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FDI_ESCROW_TXN.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 비거주자 NRO 송금 FY 누적 : NRO 잔액(자산매각·기타) 해외송금 FY USD 1M 한도. 경상소득은 별도 집계.
CREATE TABLE TB_NR_REPAT_SUM (
  CUST_NO                  VARCHAR2(8) NOT NULL,
  FY                       VARCHAR2(7) NOT NULL,
  CUM_USD_CAPITAL          NUMBER(18,2) NOT NULL,
  CUM_USD_CURRENT          NUMBER(18,2) NOT NULL,
  TXN_CNT                  NUMBER(6) NOT NULL,
  CONSTRAINT PK_NR_REPAT_SUM PRIMARY KEY (CUST_NO, FY)
);
COMMENT ON TABLE TB_NR_REPAT_SUM IS '비거주자 NRO 송금 FY 누적';
COMMENT ON COLUMN TB_NR_REPAT_SUM.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_NR_REPAT_SUM.FY IS '회계연도';
COMMENT ON COLUMN TB_NR_REPAT_SUM.CUM_USD_CAPITAL IS '자산·잔액 송금 누적(USD) - ≤ NRO_REPAT_LIMIT_USD';
COMMENT ON COLUMN TB_NR_REPAT_SUM.CUM_USD_CURRENT IS '경상소득 송금 누적(USD) - 한도 외, 세후 증빙';
COMMENT ON COLUMN TB_NR_REPAT_SUM.TXN_CNT IS '건수';

-- 환전 거래 : 송금과 분리된 환전 원장: 계좌간·외화간·외화현찰·지점 자기계정. GST(32(2))와 딜 맵핑 포함.
CREATE TABLE TB_FX_EXCHANGE (
  FX_REF_NO                VARCHAR2(16) NOT NULL,
  FX_TYPE                  VARCHAR2(8) NOT NULL,
  CUST_NO                  VARCHAR2(8),
