  SELL_CCY                 VARCHAR2(3) NOT NULL,
  SELL_AMT                 NUMBER(18,2) NOT NULL,
  SELL_ACCT_NO             VARCHAR2(16),
  BUY_CCY                  VARCHAR2(3) NOT NULL,
  BUY_AMT                  NUMBER(18,2) NOT NULL,
  BUY_ACCT_NO              VARCHAR2(16),
  RATE                     NUMBER(15,6) NOT NULL,
  RATE_SRC                 VARCHAR2(4) NOT NULL,
  DEAL_REF_NO              VARCHAR2(16),
  RBI_REF_RATE             NUMBER(15,6),
  INR_EQV_AMT              NUMBER(18,2) NOT NULL,
  PURPOSE_CODE             VARCHAR2(5),
  PAN_SNAP                 VARCHAR2(10),
  PASSPORT_NO              VARCHAR2(20),
  CDF_NO                   VARCHAR2(20),
  ENCASH_CERT_YN           VARCHAR2(1),
  FX_STS                   VARCHAR2(2) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
