-- 고시환율(Rate Card) : 통화별 TT/현찰 매입·매도율. 시간대별 회차 관리, 자금팀 승인 후 게시.
CREATE TABLE TB_FX_RATE_CARD (
  RATE_DT                  DATE NOT NULL,
  RATE_SEQ                 NUMBER(3) NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  QUOTE_UNIT               NUMBER(5) NOT NULL,
  MID_RATE                 NUMBER(15,6) NOT NULL,
  TT_BUY                   NUMBER(15,6) NOT NULL,
  TT_SELL                  NUMBER(15,6) NOT NULL,
  CASH_BUY                 NUMBER(15,6),
  CASH_SELL                NUMBER(15,6),
  RBI_REF_RATE             NUMBER(15,6),
  PUBLISH_TS               TIMESTAMP NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_RATE_CARD PRIMARY KEY (RATE_DT, RATE_SEQ, CCY)
);
COMMENT ON TABLE TB_FX_RATE_CARD IS '고시환율(Rate Card)';
COMMENT ON COLUMN TB_FX_RATE_CARD.RATE_DT IS '고시일';
COMMENT ON COLUMN TB_FX_RATE_CARD.RATE_SEQ IS '회차';
COMMENT ON COLUMN TB_FX_RATE_CARD.CCY IS '통화 - USD/EUR/JPY/KRW/GBP/AED 등';
COMMENT ON COLUMN TB_FX_RATE_CARD.QUOTE_UNIT IS '표시단위 - JPY·KRW는 100단위 표시 가능';
COMMENT ON COLUMN TB_FX_RATE_CARD.MID_RATE IS '기준율';
COMMENT ON COLUMN TB_FX_RATE_CARD.TT_BUY IS 'TT 매입율';
COMMENT ON COLUMN TB_FX_RATE_CARD.TT_SELL IS 'TT 매도율';
COMMENT ON COLUMN TB_FX_RATE_CARD.CASH_BUY IS '현찰 매입율 - 현찰 미취급 통화 NULL';
COMMENT ON COLUMN TB_FX_RATE_CARD.CASH_SELL IS '현찰 매도율';
COMMENT ON COLUMN TB_FX_RATE_CARD.RBI_REF_RATE IS 'RBI/FBIL 기준율 - GST 과세표준용';
COMMENT ON COLUMN TB_FX_RATE_CARD.PUBLISH_TS IS '게시시각';
COMMENT ON COLUMN TB_FX_RATE_CARD.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_RATE_CARD.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_RATE_CARD.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_RATE_CARD.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_RATE_CARD.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 외화현찰 재고 : 통화·권종별 시재. 현찰 매입/판매 시 자동 증감, 일마감 실사 대사.
CREATE TABLE TB_FX_CASH_STOCK (
  STOCK_DT                 DATE NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  DENOM                    NUMBER(8) NOT NULL,
  OPEN_QTY                 NUMBER(8) NOT NULL,
  IN_QTY                   NUMBER(8) NOT NULL,
  OUT_QTY                  NUMBER(8) NOT NULL,
  CLOSE_QTY                NUMBER(8) NOT NULL,
  VERIFIED_YN              VARCHAR2(1) NOT NULL,
  CONSTRAINT PK_FX_CASH_STOCK PRIMARY KEY (STOCK_DT, CCY, DENOM)
);
COMMENT ON TABLE TB_FX_CASH_STOCK IS '외화현찰 재고';
COMMENT ON COLUMN TB_FX_CASH_STOCK.STOCK_DT IS '기준일';
COMMENT ON COLUMN TB_FX_CASH_STOCK.CCY IS '통화';
COMMENT ON COLUMN TB_FX_CASH_STOCK.DENOM IS '권종 - 예: USD 100/50/20, KRW 50000/10000';
COMMENT ON COLUMN TB_FX_CASH_STOCK.OPEN_QTY IS '전일 수량';
COMMENT ON COLUMN TB_FX_CASH_STOCK.IN_QTY IS '매입 수량';
COMMENT ON COLUMN TB_FX_CASH_STOCK.OUT_QTY IS '판매 수량';
COMMENT ON COLUMN TB_FX_CASH_STOCK.CLOSE_QTY IS '마감 수량 - = OPEN + IN - OUT, 실사와 대사';
COMMENT ON COLUMN TB_FX_CASH_STOCK.VERIFIED_YN IS '실사확인';

-- SWIFT 메시지 카탈로그 : 지원 메시지 유형과 MT↔MX 대응, 송신 형식, 자동생성 원천.
CREATE TABLE TB_SWIFT_MSG_TYPE (
  MSG_TYPE                 VARCHAR2(12) NOT NULL,
  STD                      VARCHAR2(2) NOT NULL,
  CATEGORY                 VARCHAR2(10) NOT NULL,
  MSG_NAME                 VARCHAR2(80) NOT NULL,
  COUNTERPART_TYPE         VARCHAR2(12),
  LIVE_FORMAT              VARCHAR2(2) NOT NULL,
  DIRECTION                VARCHAR2(3) NOT NULL,
  AUTO_SRC                 VARCHAR2(60),
  ROUTE_TO                 VARCHAR2(20),
  CONSTRAINT PK_SWIFT_MSG_TYPE PRIMARY KEY (MSG_TYPE)
);
COMMENT ON TABLE TB_SWIFT_MSG_TYPE IS 'SWIFT 메시지 카탈로그';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.MSG_TYPE IS '메시지 유형 - MT950, pacs.009 등';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.STD IS '표준 - MT/MX';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.CATEGORY IS '카테고리 - 1/2/3/7/9, pacs/camt';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.MSG_NAME IS '명칭';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.COUNTERPART_TYPE IS '대응 유형 - MT↔MX';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.LIVE_FORMAT IS '현재 송신 형식 - MT/MX (SWIFT_MX_CUTOVER 기준)';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.DIRECTION IS '방향 - IN/OUT/BOTH';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.AUTO_SRC IS '자동생성 원천 - 화면/배치';
COMMENT ON COLUMN TB_SWIFT_MSG_TYPE.ROUTE_TO IS '수신 시 연결 화면';

-- SWIFT 메시지 : 송수신 전 메시지(MT/MX). 자동생성·수기작성 모두 Maker-Checker 후 송신.
CREATE TABLE TB_SWIFT_MSG (
  MSG_ID                   VARCHAR2(20) NOT NULL,
  DIRECTION                VARCHAR2(1) NOT NULL,
  MSG_TYPE                 VARCHAR2(12) NOT NULL,
  ORIGIN                   VARCHAR2(4) NOT NULL,
  SENDER_BIC               VARCHAR2(11) NOT NULL,
  RECEIVER_BIC             VARCHAR2(11) NOT NULL,
  TRN                      VARCHAR2(35) NOT NULL,
  RELATED_REF              VARCHAR2(35),
  UETR                     VARCHAR2(36),
  VALUE_DT                 DATE,
  CCY                      VARCHAR2(3),
  AMT                      NUMBER(18,2),
  SRC_TABLE                VARCHAR2(30),
  SRC_KEY                  VARCHAR2(40),
  MSG_TEXT                 CLOB NOT NULL,
  PARSED_JSON              CLOB,
  MSG_STS                  VARCHAR2(6) NOT NULL,
  ACK_INFO                 VARCHAR2(60),
  SESSION_SEQ              VARCHAR2(20),
  PDE_YN                   VARCHAR2(1),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_SWIFT_MSG PRIMARY KEY (MSG_ID)
);
COMMENT ON TABLE TB_SWIFT_MSG IS 'SWIFT 메시지';
COMMENT ON COLUMN TB_SWIFT_MSG.MSG_ID IS '메시지ID';
COMMENT ON COLUMN TB_SWIFT_MSG.DIRECTION IS '방향 - O/I';
COMMENT ON COLUMN TB_SWIFT_MSG.MSG_TYPE IS '유형 - TB_SWIFT_MSG_TYPE';
COMMENT ON COLUMN TB_SWIFT_MSG.ORIGIN IS '생성방식 - AUTO자동/MANU수기/RPR수리/RSND재발송';
COMMENT ON COLUMN TB_SWIFT_MSG.SENDER_BIC IS '송신 BIC';
COMMENT ON COLUMN TB_SWIFT_MSG.RECEIVER_BIC IS '수신 BIC - RMA 확인';
COMMENT ON COLUMN TB_SWIFT_MSG.TRN IS '참조(:20:/MsgId) - MT 16x / MX 35x';
COMMENT ON COLUMN TB_SWIFT_MSG.RELATED_REF IS '관련참조(:21:)';
COMMENT ON COLUMN TB_SWIFT_MSG.UETR IS 'UETR';
COMMENT ON COLUMN TB_SWIFT_MSG.VALUE_DT IS '결제일 - 통화국·지점 영업일 검증(R-HOL-01)';
COMMENT ON COLUMN TB_SWIFT_MSG.CCY IS '통화';
COMMENT ON COLUMN TB_SWIFT_MSG.AMT IS '금액';
COMMENT ON COLUMN TB_SWIFT_MSG.SRC_TABLE IS '원천 - 자동생성 원천/수신 연결 대상';
COMMENT ON COLUMN TB_SWIFT_MSG.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_SWIFT_MSG.MSG_TEXT IS '원문 - MT 블록 4 / MX XML';
COMMENT ON COLUMN TB_SWIFT_MSG.PARSED_JSON IS '파싱 결과 - 필드별 값';
COMMENT ON COLUMN TB_SWIFT_MSG.MSG_STS IS '상태 - CODE:SW_STS';
COMMENT ON COLUMN TB_SWIFT_MSG.ACK_INFO IS 'ACK/NAK - NAK 오류코드 → Repair 큐';
COMMENT ON COLUMN TB_SWIFT_MSG.SESSION_SEQ IS '세션·순번';
COMMENT ON COLUMN TB_SWIFT_MSG.PDE_YN IS '중복발송 표시 - 재발송 시 PDE';
COMMENT ON COLUMN TB_SWIFT_MSG.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_SWIFT_MSG.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_SWIFT_MSG.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_SWIFT_MSG.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_SWIFT_MSG.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_SWIFT_MSG_1 ON TB_SWIFT_MSG (MSG_TYPE,VALUE_DT);
CREATE INDEX IX_SWIFT_MSG_2 ON TB_SWIFT_MSG (TRN);
CREATE INDEX IX_SWIFT_MSG_3 ON TB_SWIFT_MSG (SRC_TABLE,SRC_KEY);

-- 상환수권(RA) : 본점이 개설한 신용장의 상환수권(MT740) - 지점이 상환은행. 대지급 후 본점에서 정산.
CREATE TABLE TB_RA_AUTH (
  RA_NO                    VARCHAR2(16) NOT NULL,
  LC_NO                    VARCHAR2(16) NOT NULL,
  ISSUING_BIC              VARCHAR2(11) NOT NULL,
  CLAIMING_BIC             VARCHAR2(11),
  CCY                      VARCHAR2(3) NOT NULL,
  RA_AMT                   NUMBER(18,2) NOT NULL,
  TOLERANCE_PCT            VARCHAR2(7),
  AVAIL_AMT                NUMBER(18,2) NOT NULL,
  EXPIRY_DT                DATE NOT NULL,
  CHG_FOR                  VARCHAR2(3) NOT NULL,
  URR725_YN                VARCHAR2(1) NOT NULL,
  RA_STS                   VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_RA_AUTH PRIMARY KEY (RA_NO)
);
COMMENT ON TABLE TB_RA_AUTH IS '상환수권(RA)';
COMMENT ON COLUMN TB_RA_AUTH.RA_NO IS 'RA 번호';
COMMENT ON COLUMN TB_RA_AUTH.LC_NO IS '신용장 번호';
COMMENT ON COLUMN TB_RA_AUTH.ISSUING_BIC IS '개설은행(본점)';
COMMENT ON COLUMN TB_RA_AUTH.CLAIMING_BIC IS '청구가능은행 - NULL = 모든 은행';
COMMENT ON COLUMN TB_RA_AUTH.CCY IS '통화 - USD/INR 등';
COMMENT ON COLUMN TB_RA_AUTH.RA_AMT IS '수권금액';
COMMENT ON COLUMN TB_RA_AUTH.TOLERANCE_PCT IS '과부족 허용(%) - +/-';
COMMENT ON COLUMN TB_RA_AUTH.AVAIL_AMT IS '잔여 수권액 - = 수권액(허용치 포함) - Σ지급';
COMMENT ON COLUMN TB_RA_AUTH.EXPIRY_DT IS '유효기일';
COMMENT ON COLUMN TB_RA_AUTH.CHG_FOR IS '상환수수료 부담 - CLM청구은행/OUR개설은행';
COMMENT ON COLUMN TB_RA_AUTH.URR725_YN IS 'URR 725 준거';
COMMENT ON COLUMN TB_RA_AUTH.RA_STS IS '상태 - OPEN/AMND/EXPD/CLSD';
COMMENT ON COLUMN TB_RA_AUTH.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_RA_AUTH.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_RA_AUTH.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_RA_AUTH.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_RA_AUTH.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 상환청구·대지급 : MT742 청구 접수 → 지급(대지급) → 본지점 미정산(Due from HO) 생성.
CREATE TABLE TB_RA_CLAIM (
  CLAIM_ID                 VARCHAR2(16) NOT NULL,
  RA_NO                    VARCHAR2(16) NOT NULL,
  CLAIM_REF                VARCHAR2(16) NOT NULL,
  CLAIMING_BIC             VARCHAR2(11) NOT NULL,
  CLAIM_AMT                NUMBER(18,2) NOT NULL,
  CLAIM_CHG                NUMBER(18,2),
  RCV_DT                   DATE NOT NULL,
  PAY_DUE_DT               DATE NOT NULL,
  REQ_VALUE_DT             DATE,
  PAY_VALUE_DT             DATE,
  PAY_METHOD               VARCHAR2(6),
  PAY_MSG_ID               VARCHAR2(20),
  HO_CUST_SETTLE_DT        DATE,
  IO_REF                   VARCHAR2(16),
  CLAIM_STS                VARCHAR2(4) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_RA_CLAIM PRIMARY KEY (CLAIM_ID)
);
COMMENT ON TABLE TB_RA_CLAIM IS '상환청구·대지급';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_ID IS '청구ID';
COMMENT ON COLUMN TB_RA_CLAIM.RA_NO IS 'RA 번호';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_REF IS '청구은행 Ref';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIMING_BIC IS '청구은행';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_AMT IS '청구금액 - ≤ AVAIL_AMT';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_CHG IS '청구은행 수수료';
COMMENT ON COLUMN TB_RA_CLAIM.RCV_DT IS '접수일';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_DUE_DT IS '지급기한 - 접수일 + 3 인도 영업일 (CAL IN)';
COMMENT ON COLUMN TB_RA_CLAIM.REQ_VALUE_DT IS '청구 결제일';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_VALUE_DT IS '실제 결제일 - 통화국 영업일(USD→US, INR→IN)';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_METHOD IS '지급방식 - PACS009/RTGS/VOSTRO';
COMMENT ON COLUMN TB_RA_CLAIM.PAY_MSG_ID IS '지급 메시지';
COMMENT ON COLUMN TB_RA_CLAIM.HO_CUST_SETTLE_DT IS '본점 고객 결제일 - 본점 통보(MT756/MT799/정산파일)';
COMMENT ON COLUMN TB_RA_CLAIM.IO_REF IS '본지점 거래 Ref';
COMMENT ON COLUMN TB_RA_CLAIM.CLAIM_STS IS '상태 - RCVD/CHKD/PAID/REJ(불일치·수권초과)';
COMMENT ON COLUMN TB_RA_CLAIM.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_RA_CLAIM.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_RA_CLAIM.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_RA_CLAIM.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_RA_CLAIM.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_RA_CLAIM_1 ON TB_RA_CLAIM (RA_NO);
CREATE INDEX IX_RA_CLAIM_2 ON TB_RA_CLAIM (PAY_DUE_DT);

-- 본지점 거래(미정산 원장) : 본점과의 채권·채무 건별 원장. 정산배치로 묶여 SETTLED 처리.
CREATE TABLE TB_IO_TXN (
  IO_REF                   VARCHAR2(16) NOT NULL,
  IO_FUND                  VARCHAR2(4) NOT NULL,
  IO_ITEM                  VARCHAR2(6) NOT NULL,
  SRC_TABLE                VARCHAR2(30) NOT NULL,
  SRC_KEY                  VARCHAR2(40) NOT NULL,
  CCY                      VARCHAR2(3) NOT NULL,
  AMT                      NUMBER(18,2) NOT NULL,
  DC                       VARCHAR2(3) NOT NULL,
  BR_VALUE_DT              DATE NOT NULL,
  HO_VALUE_DT              DATE,
  FLOAT_DAYS               NUMBER(4),
  SETTLE_STS               VARCHAR2(7) NOT NULL,
  BATCH_ID                 VARCHAR2(16),
  SETTLED_AMT              NUMBER(18,2) NOT NULL,
  SETTLED_DT               DATE,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_IO_TXN PRIMARY KEY (IO_REF)
);
COMMENT ON TABLE TB_IO_TXN IS '본지점 거래(미정산 원장)';
COMMENT ON COLUMN TB_IO_TXN.IO_REF IS '본지점 Ref';
COMMENT ON COLUMN TB_IO_TXN.IO_FUND IS '기금 구분 - GAP/EULA/EULB. GAP은 이자·정산배치 제외';
COMMENT ON COLUMN TB_IO_TXN.IO_ITEM IS '거래유형 - CODE:IO_ITEM';
COMMENT ON COLUMN TB_IO_TXN.SRC_TABLE IS '원천 - TB_RA_CLAIM/TB_FX_REMIT_MST/TB_SWIFT_MSG';
COMMENT ON COLUMN TB_IO_TXN.SRC_KEY IS '원천키';
COMMENT ON COLUMN TB_IO_TXN.CCY IS '통화';
COMMENT ON COLUMN TB_IO_TXN.AMT IS '금액';
COMMENT ON COLUMN TB_IO_TXN.DC IS '채권/채무 - DFH(Due from HO 채권)/DTH(Due to HO 채무)';
