COMMENT ON COLUMN TB_IO_FLOAT_ADJ.HO_VALUE_DT IS '본점 결제일';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.BR_VALUE_DT IS '지점 결제일';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.DAYS IS '일수(±) - + 지점 선지급(지점 자금부담) / - 본점 선수취';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.RATE_PCT IS '적용금리 - TB_IO_RATE(INT) all-in';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.INT_AMT IS '이자 - AMT × RATE × DAYS / 일수기준';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.TREAT IS '처리 - ABSORB/SETTLE (IO_FLOAT_ABSORB_USD)';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.GL_CODE IS '계정 - 내부대체 손익 / 본지점 이자';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.CUST_CLAIM_YN IS '고객 청구 - 기본 N (휴일 차이는 고객에게 청구하지 않음)';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_IO_FLOAT_ADJ.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';

-- 확인서·증명서 발급이력 : FIRC(FM-FDI-01)·당발확인서(FM-OUT-01)·타발확인서(FM-IN-01) 발급/재발급/정정 이력. 원본은 원천 1건당 1회.
CREATE TABLE TB_FX_ADVICE_ISSUE (
  ISSUE_NO                 VARCHAR2(30) NOT NULL,
  FORM_ID                  VARCHAR2(10) NOT NULL,
  SRC_TABLE                VARCHAR2(30) NOT NULL,
  SRC_KEY                  VARCHAR2(40) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  ISSUE_TYPE               VARCHAR2(3) NOT NULL,
  ORG_ISSUE_NO             VARCHAR2(30),
  ISSUE_SEQ                NUMBER(3) NOT NULL,
  ISSUE_DT                 DATE NOT NULL,
  ISSUE_RSN                VARCHAR2(200),
  DELIVERY                 VARCHAR2(4) NOT NULL,
  VERIFY_CODE              VARCHAR2(16) NOT NULL,
  SNAPSHOT_JSON            CLOB NOT NULL,
  DMS_KEY                  VARCHAR2(64),
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_FX_ADVICE_ISSUE PRIMARY KEY (ISSUE_NO)
);
COMMENT ON TABLE TB_FX_ADVICE_ISSUE IS '확인서·증명서 발급이력';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_NO IS '발급번호 - 서식약어/지점/FY/일련 (예: FIRC/NOI/2026-27/000041)';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.FORM_ID IS '서식ID - FM-FDI-01 / FM-OUT-01 / FM-IN-01';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SRC_TABLE IS '원천테이블 - TB_FDI_INFLOW / TB_FX_REMIT_MST';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SRC_KEY IS '원천키 - FDI_REF_NO 또는 REMIT_REF_NO';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.CUST_NO IS '고객번호';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_TYPE IS '발급구분 - ORG원본/DUP재발급/AMD정정/CXL취소';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ORG_ISSUE_NO IS '원본 발급번호 - DUP/AMD/CXL 시 필수';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_SEQ IS '발급차수 - 원본=1, 재발급마다 +1';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_DT IS '발급일';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.ISSUE_RSN IS '재발급/정정 사유';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.DELIVERY IS '전달방식 - PRNT창구출력/MAIL/INET인터넷뱅킹';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.VERIFY_CODE IS '진위확인코드 - HMAC(발급번호+금액+일자) 앞 16자리, QR 표시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.SNAPSHOT_JSON IS '발급내용 스냅샷 - 발급 시점 표기값 전체 - 재발급은 이 값으로 동일 재현';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.DMS_KEY IS 'PDF 보관키';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.REG_USER_ID IS '등록자';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_FX_ADVICE_ISSUE.APPR_USER_ID IS '승인자(Maker-Checker) - 등록자와 동일인 불가';
CREATE INDEX IX_FX_ADVICE_ISSUE_1 ON TB_FX_ADVICE_ISSUE (SRC_TABLE,SRC_KEY);
CREATE INDEX IX_FX_ADVICE_ISSUE_2 ON TB_FX_ADVICE_ISSUE (CUST_NO,ISSUE_DT);

-- 무역금융 거래(BILL_MASTER) : 어음할인·매입·LC 매입·D/A·D/P 추심·오픈어카운트·TReDS 통합 원장. 거래유형별 하위 테이블 1:1.
CREATE TABLE TB_TF_BILL (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  BILL_CATEGORY            VARCHAR2(14) NOT NULL,
  BILL_TYPE                VARCHAR2(14) NOT NULL,
  DIRECTION                VARCHAR2(6) NOT NULL,
  CUST_NO                  VARCHAR2(8) NOT NULL,
  DRAWER_NAME              VARCHAR2(140) NOT NULL,
  DRAWEE_NAME              VARCHAR2(140) NOT NULL,
  DRAWEE_CTRY              VARCHAR2(2),
  COUNTERPARTY_BANK_BIC    VARCHAR2(11),
  LC_REF                   VARCHAR2(16),
  CCY                      VARCHAR2(3) NOT NULL,
  BILL_AMT                 NUMBER(18,2) NOT NULL,
  FX_RATE                  NUMBER(15,6),
  INR_EQV                  NUMBER(18,2) NOT NULL,
  BILL_DT                  DATE NOT NULL,
  TENOR_DAYS               NUMBER(4),
  DUE_DT                   DATE,
  SHIPMENT_DT              DATE,
  REALIZE_DUE_DT           DATE,
  SB_MGMT_NO               VARCHAR2(16),
  BOE_MGMT_NO              VARCHAR2(16),
  HS_CODE                  VARCHAR2(8),
  PURPOSE_CODE             VARCHAR2(5),
  ECGC_COVER_YN            VARCHAR2(1),
  PSL_CAT                  VARCHAR2(10),
  BILL_STS                 VARCHAR2(10) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TF_BILL PRIMARY KEY (BILL_REF)
);
COMMENT ON TABLE TB_TF_BILL IS '무역금융 거래(BILL_MASTER)';
COMMENT ON COLUMN TB_TF_BILL.BILL_REF IS '어음참조번호 - BR-지점-YYMMDD-일련 / TReDS는 TR-플랫폼-YYMMDD-일련. SFMS E2E ID로 사용(35자 이내)';
COMMENT ON COLUMN TB_TF_BILL.BILL_CATEGORY IS '거래유형 - CODE:BILL_CATEGORY';
COMMENT ON COLUMN TB_TF_BILL.BILL_TYPE IS '어음유형 - EXPORT_USANCE/EXPORT_SIGHT/IMPORT_USANCE/IMPORT_SIGHT/INLAND_DEMAND/INLAND_USANCE/CLEAN';
COMMENT ON COLUMN TB_TF_BILL.DIRECTION IS '무역방향 - EXPORT/IMPORT/INLAND';
COMMENT ON COLUMN TB_TF_BILL.CUST_NO IS '고객번호 - 한도·여신 심사 대상(수출자/수입자)';
COMMENT ON COLUMN TB_TF_BILL.DRAWER_NAME IS '발행인';
COMMENT ON COLUMN TB_TF_BILL.DRAWEE_NAME IS '지급인';
COMMENT ON COLUMN TB_TF_BILL.DRAWEE_CTRY IS '지급인 국가 - 국가한도·국가 프리미엄';
COMMENT ON COLUMN TB_TF_BILL.COUNTERPARTY_BANK_BIC IS '추심·개설은행 - LC 매입은 개설은행(신용 프리미엄 평가 대상)';
COMMENT ON COLUMN TB_TF_BILL.LC_REF IS '신용장 참조 - LC 기반 매입(NEGOTIATION)·인수';
COMMENT ON COLUMN TB_TF_BILL.CCY IS '통화';
COMMENT ON COLUMN TB_TF_BILL.BILL_AMT IS '어음금액';
COMMENT ON COLUMN TB_TF_BILL.FX_RATE IS '적용환율 - FEDAI 고시 대비 편차 검증';
COMMENT ON COLUMN TB_TF_BILL.INR_EQV IS 'INR 환산';
COMMENT ON COLUMN TB_TF_BILL.BILL_DT IS '어음일자';
COMMENT ON COLUMN TB_TF_BILL.TENOR_DAYS IS '만기일수';
COMMENT ON COLUMN TB_TF_BILL.DUE_DT IS '만기일 - 휴일이면 영업일 조정(R-HOL-01)';
COMMENT ON COLUMN TB_TF_BILL.SHIPMENT_DT IS '선적일 - 회수기한·유전스 기산';
COMMENT ON COLUMN TB_TF_BILL.REALIZE_DUE_DT IS '회수기한 - 수출: 선적일 + TF_EXP_REALIZE_MONTHS';
COMMENT ON COLUMN TB_TF_BILL.SB_MGMT_NO IS 'Shipping Bill - 수출 - TB_TRD_SHIPPING_BILL 연결(EDPMS)';
COMMENT ON COLUMN TB_TF_BILL.BOE_MGMT_NO IS 'Bill of Entry - 수입 - TB_TRD_BOE 연결(IDPMS)';
COMMENT ON COLUMN TB_TF_BILL.HS_CODE IS 'HS Code - 수입 유전스 상한(자본재 여부) 판정';
COMMENT ON COLUMN TB_TF_BILL.PURPOSE_CODE IS 'Purpose';
COMMENT ON COLUMN TB_TF_BILL.ECGC_COVER_YN IS 'ECGC 부보 - 리스크 프리미엄 차등';
COMMENT ON COLUMN TB_TF_BILL.PSL_CAT IS '우선대출 분류 - EXPORT/MSME/NONE (TReDS MSME 자동)';
COMMENT ON COLUMN TB_TF_BILL.BILL_STS IS '상태 - DRAFT/SUBMIT/APPROVED/DISBURSED/MATURED/OVERDUE/REALIZED/CRYSTAL/NPA/CLOSED/CANCEL';
COMMENT ON COLUMN TB_TF_BILL.REG_USER_ID IS '등록자(Maker)';
COMMENT ON COLUMN TB_TF_BILL.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_TF_BILL.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_TF_BILL.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_TF_BILL.APPR_USER_ID IS '승인자(Checker) - Maker와 동일인 불가';
COMMENT ON COLUMN TB_TF_BILL.AUTH_USER_ID IS 'Authorizer - ALCO 기준금액 초과 시';
CREATE INDEX IX_TF_BILL_1 ON TB_TF_BILL (CUST_NO,BILL_STS);
CREATE INDEX IX_TF_BILL_2 ON TB_TF_BILL (DUE_DT);
CREATE INDEX IX_TF_BILL_3 ON TB_TF_BILL (LC_REF);

-- 선적서류 : B/L·Invoice·P/L·보험·S/B 등 서류 체크리스트(오픈어카운트는 선택).
CREATE TABLE TB_TF_DOC (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  SEQ                      NUMBER(3) NOT NULL,
  DOC_TYPE                 VARCHAR2(6) NOT NULL,
  DOC_NO                   VARCHAR2(35),
  DOC_DT                   DATE,
  ORIG_CNT                 NUMBER(2),
  COPY_CNT                 NUMBER(2),
  DOC_STS                  VARCHAR2(6) NOT NULL,
  CONSTRAINT PK_TF_DOC PRIMARY KEY (BILL_REF, SEQ)
);
COMMENT ON TABLE TB_TF_DOC IS '선적서류';
COMMENT ON COLUMN TB_TF_DOC.BILL_REF IS '어음참조번호';
COMMENT ON COLUMN TB_TF_DOC.SEQ IS '순번';
COMMENT ON COLUMN TB_TF_DOC.DOC_TYPE IS '서류유형 - BL/AWB/INV/PL/INS/SB/BOE/COO/BOX';
COMMENT ON COLUMN TB_TF_DOC.DOC_NO IS '서류번호';
COMMENT ON COLUMN TB_TF_DOC.DOC_DT IS '서류일자';
COMMENT ON COLUMN TB_TF_DOC.ORIG_CNT IS '원본 수';
COMMENT ON COLUMN TB_TF_DOC.COPY_CNT IS '사본 수';
COMMENT ON COLUMN TB_TF_DOC.DOC_STS IS '상태 - RCVD/CHKD/MISS/DISC(하자)';

-- 할인계산 : 기준금리·기간스프레드·신용·국가·정책 프리미엄 5단계와 공제액·순지급액. 산출 근거 전부 저장.
CREATE TABLE TB_TF_DISCOUNT (
  BILL_REF                 VARCHAR2(20) NOT NULL,
  RATE_TYPE                VARCHAR2(6) NOT NULL,
  BASE_SRC                 VARCHAR2(20) NOT NULL,
  BASE_RATE                NUMBER(9,6) NOT NULL,
  TENOR_SPREAD             NUMBER(9,6) NOT NULL,
  CREDIT_PREM              NUMBER(9,6) NOT NULL,
  ISSUER_GRADE             VARCHAR2(1),
  COUNTRY_PREM             NUMBER(9,6) NOT NULL,
  POLICY_PREM              NUMBER(9,6) NOT NULL,
  EFF_RATE                 NUMBER(9,6) NOT NULL,
  DAYCOUNT                 VARCHAR2(8) NOT NULL,
  DISC_DAYS                NUMBER(4) NOT NULL,
  DISC_AMT                 NUMBER(18,2) NOT NULL,
  COMMISSION               NUMBER(18,2) NOT NULL,
  GST_AMT                  NUMBER(18,2) NOT NULL,
  MSG_CHG                  NUMBER(18,2),
  NET_PROCEEDS             NUMBER(18,2) NOT NULL,
  DISC_PCT                 NUMBER(7,4),
  TOTAL_DED_PCT            NUMBER(7,4),
  NET_PCT                  NUMBER(7,4),
  INCOME_RECOG             VARCHAR2(7) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TF_DISCOUNT PRIMARY KEY (BILL_REF)
);
COMMENT ON TABLE TB_TF_DISCOUNT IS '할인계산';
COMMENT ON COLUMN TB_TF_DISCOUNT.BILL_REF IS '어음참조번호';
COMMENT ON COLUMN TB_TF_DISCOUNT.RATE_TYPE IS '금리유형 - MCLR/EBLR/SOFR/EURIBOR/FIXED';
COMMENT ON COLUMN TB_TF_DISCOUNT.BASE_SRC IS '기준금리 출처 - INR: MCLR 1년물(또는 EBLR) / FCY: SOFR·EURIBOR + 조달마진';
COMMENT ON COLUMN TB_TF_DISCOUNT.BASE_RATE IS '① 기준금리 - 적용 하한(R-TF-12)';
COMMENT ON COLUMN TB_TF_DISCOUNT.TENOR_SPREAD IS '② 기간 스프레드 - ≤90일 0.25 / 91~180 0.50 / >180 0.85 (ALCO)';
COMMENT ON COLUMN TB_TF_DISCOUNT.CREDIT_PREM IS '③ 신용 프리미엄 - LC: 개설은행 등급 / 그 외: 지급인·수출자 등급';
COMMENT ON COLUMN TB_TF_DISCOUNT.ISSUER_GRADE IS '개설은행 등급 - S/A/B/C/D/E (TB_TF_ISSUER_EVAL)';
COMMENT ON COLUMN TB_TF_DISCOUNT.COUNTRY_PREM IS '④ 국가 프리미엄 - OECD CRC 0~7';
COMMENT ON COLUMN TB_TF_DISCOUNT.POLICY_PREM IS '⑤ 정책 프리미엄 - -0.50 ~ +1.00, 결재선 차등(TB_TF_POLICY_ADJ)';
COMMENT ON COLUMN TB_TF_DISCOUNT.EFF_RATE IS '적용금리 - = ①+②+③+④+⑤, 하한·상한 검증';
COMMENT ON COLUMN TB_TF_DISCOUNT.DAYCOUNT IS '일수기준 - INR ACT/365, FCY ACT/360 (관리자 변경 가능)';
COMMENT ON COLUMN TB_TF_DISCOUNT.DISC_DAYS IS '할인일수';
COMMENT ON COLUMN TB_TF_DISCOUNT.DISC_AMT IS '할인료 - = 액면 × 적용금리 × 일수 / 일수기준';
COMMENT ON COLUMN TB_TF_DISCOUNT.COMMISSION IS '취급수수료';
COMMENT ON COLUMN TB_TF_DISCOUNT.GST_AMT IS 'GST - 수수료·전신료 과세(R-GST-*). 할인료(이자)는 비과세';
COMMENT ON COLUMN TB_TF_DISCOUNT.MSG_CHG IS '전신료 - SWIFT/SFMS';
COMMENT ON COLUMN TB_TF_DISCOUNT.NET_PROCEEDS IS '순지급액 - = 액면 - 할인료 - 수수료 - GST - 전신료 → A/P 계상';
COMMENT ON COLUMN TB_TF_DISCOUNT.DISC_PCT IS '할인비율';
COMMENT ON COLUMN TB_TF_DISCOUNT.TOTAL_DED_PCT IS '총공제비율';
COMMENT ON COLUMN TB_TF_DISCOUNT.NET_PCT IS '순지급비율';
COMMENT ON COLUMN TB_TF_DISCOUNT.INCOME_RECOG IS '수익인식 - ACCRUAL(미실현할인 일할) / UPFRONT';
COMMENT ON COLUMN TB_TF_DISCOUNT.REG_USER_ID IS '등록자(Maker)';
COMMENT ON COLUMN TB_TF_DISCOUNT.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_TF_DISCOUNT.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_TF_DISCOUNT.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_TF_DISCOUNT.APPR_USER_ID IS '승인자(Checker) - Maker와 동일인 불가';
COMMENT ON COLUMN TB_TF_DISCOUNT.AUTH_USER_ID IS 'Authorizer - ALCO 기준금액 초과 시';

-- 개설은행 평가 : 개설은행 3축(바젤III 40·외부등급 35·거래이력 25) 100점 → S~E 등급. 반기 재평가 + 이벤트 재평가.
CREATE TABLE TB_TF_ISSUER_EVAL (
  BANK_BIC                 VARCHAR2(11) NOT NULL,
  EVAL_DT                  DATE NOT NULL,
  BANK_CTRY                VARCHAR2(2) NOT NULL,
  AX1_SCORE                NUMBER(5,2),
  AX2_SCORE                NUMBER(5,2),
  AX3_SCORE                NUMBER(5,2),
  REFUSAL_CNT_24M          NUMBER(4),
  TOTAL_SCORE              NUMBER(5,2) NOT NULL,
  GRADE                    VARCHAR2(1) NOT NULL,
  BASE_PREMIUM             NUMBER(6,4),
  SINGLE_BANK_CAP_PCT      NUMBER(5,2),
  NEXT_EVAL_DT             DATE NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_TF_ISSUER_EVAL PRIMARY KEY (BANK_BIC, EVAL_DT)
);
COMMENT ON TABLE TB_TF_ISSUER_EVAL IS '개설은행 평가';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.BANK_BIC IS '개설은행 BIC';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.EVAL_DT IS '평가일';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.BANK_CTRY IS '소재국';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AX1_SCORE IS '제1축 재무건전성 - CRAR·CET1·NPL·LCR·NSFR·레버리지 (Pillar 3). 자료 없으면 0, 제2축 55%로 상향';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AX2_SCORE IS '제2축 외부등급 - Moody''s/S&P/Fitch/CRISIL, 국가등급 상한';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.AX3_SCORE IS '제3축 당행 거래이력 - 최근 24개월 승인불가(IFN/MT 734)·지급지연·분쟁 자동집계';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.REFUSAL_CNT_24M IS '거절(734) 건수 - TB_TF_LC_PRES·TB_SFMS_MSG(IFN 734)에서 자동';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.TOTAL_SCORE IS '종합점수';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.GRADE IS '등급 - S≥90 / A≥75 / B≥60 / C≥45 / D≥30 / E<30';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.BASE_PREMIUM IS '기본 프리미엄 - S 0.15 / A 0.35 / B 0.60 / C 1.00 / D 1.75 / E 취급불가';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.SINGLE_BANK_CAP_PCT IS '단일은행 상한(기본자본 %) - S 10 / A 8 / B 5 / C 3 / D 1 / E 0';
COMMENT ON COLUMN TB_TF_ISSUER_EVAL.NEXT_EVAL_DT IS '차기 평가일 - 반기. 등급 변동·부도·국가등급 하향 시 즉시';
