-- 보증서(BG/SBLC) : 국내 BG(SFMS IFN 760 + IFN 760COV 필수), 해외 BG(MT760 / 역보증 기반 발행), SBLC. URDG 758 / ISP98.
CREATE TABLE TB_BG_MASTER (
  BG_REF                   VARCHAR2(16) NOT NULL,
