  BENE_NAME                VARCHAR2(140) NOT NULL,
  BENE_BANK_IFSC           VARCHAR2(11),
  BENE_BANK_BIC            VARCHAR2(11),
  CCY                      VARCHAR2(3) NOT NULL,
  BG_AMT                   NUMBER(18,2) NOT NULL,
  ISSUE_DT                 DATE NOT NULL,
  EXPIRY_DT                DATE NOT NULL,
  CLAIM_EXPIRY_DT          DATE NOT NULL,
  TENOR_MONTHS             NUMBER(4),
  E_BG_YN                  VARCHAR2(1) NOT NULL,
  NESL_REF                 VARCHAR2(30),
  STAMP_DUTY_AMT           NUMBER(18,2),
  SFMS_760COV_ID           VARCHAR2(20),
  COUNTER_GTEE_REF         VARCHAR2(30),
