-- 보증 청구(Invocation) : 청구 접수·요건 심사·지급·대지급(Devolvement) → 여신 전환.
CREATE TABLE TB_BG_CLAIM (
  CLAIM_ID                 VARCHAR2(16) NOT NULL,
  BG_REF                   VARCHAR2(16) NOT NULL,
  CLAIM_DT                 DATE NOT NULL,
  CLAIM_AMT                NUMBER(18,2) NOT NULL,
