  PAY_DUE_DT               DATE,
  PAID_DT                  DATE,
  DEVOLVE_LOAN_REF         VARCHAR2(20),
  CLAIM_STS                VARCHAR2(6) NOT NULL,
  REG_USER_ID              VARCHAR2(10) NOT NULL,
  REG_TS                   TIMESTAMP NOT NULL,
  UPD_USER_ID              VARCHAR2(10),
  UPD_TS                   TIMESTAMP,
  APPR_USER_ID             VARCHAR2(10),
  AUTH_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_BG_CLAIM PRIMARY KEY (CLAIM_ID)
);
COMMENT ON TABLE TB_BG_CLAIM IS '보증 청구(Invocation)';
COMMENT ON COLUMN TB_BG_CLAIM.CLAIM_ID IS '청구ID';
COMMENT ON COLUMN TB_BG_CLAIM.BG_REF IS '보증 참조';
COMMENT ON COLUMN TB_BG_CLAIM.CLAIM_DT IS '청구일 - ≤ CLAIM_EXPIRY_DT';
COMMENT ON COLUMN TB_BG_CLAIM.CLAIM_AMT IS '청구금액 - ≤ 잔여 보증금액';
COMMENT ON COLUMN TB_BG_CLAIM.COMPLIANT_YN IS '청구요건 일치 - URDG 758 Art.15·20 / 보증서 문언';
COMMENT ON COLUMN TB_BG_CLAIM.PAY_DUE_DT IS '지급기한 - URDG: 제시 다음날부터 5영업일 심사';
COMMENT ON COLUMN TB_BG_CLAIM.PAID_DT IS '지급일';
COMMENT ON COLUMN TB_BG_CLAIM.DEVOLVE_LOAN_REF IS '대지급 여신 - 의뢰인 미상환 시 여신 전환·자산건전성 대상';
COMMENT ON COLUMN TB_BG_CLAIM.CLAIM_STS IS '상태 - RCVD/EXAM/PAID/REJECT/DEVOLV';
COMMENT ON COLUMN TB_BG_CLAIM.REG_USER_ID IS '등록자(Maker)';
COMMENT ON COLUMN TB_BG_CLAIM.REG_TS IS '등록일시';
COMMENT ON COLUMN TB_BG_CLAIM.UPD_USER_ID IS '수정자';
COMMENT ON COLUMN TB_BG_CLAIM.UPD_TS IS '수정일시';
COMMENT ON COLUMN TB_BG_CLAIM.APPR_USER_ID IS '승인자(Checker) - Maker와 동일인 불가';
COMMENT ON COLUMN TB_BG_CLAIM.AUTH_USER_ID IS 'Authorizer - ALCO 기준금액 초과 시';

-- 자산건전성 일별 : 연체일수(DPD) → SMA-0/1/2·NPA, 충당금, CRILC 보고 대상.
CREATE TABLE TB_TF_ASSET_CLASS (
