  INCOME_STOP_YN           VARCHAR2(1),
  CONSTRAINT PK_TF_ASSET_CLASS PRIMARY KEY (BILL_REF, AS_OF_DT)
);
COMMENT ON TABLE TB_TF_ASSET_CLASS IS '자산건전성 일별';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.BILL_REF IS '거래 Ref - BILL·LC 인수·BG 대지급';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.AS_OF_DT IS '기준일';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.DPD IS '연체일수';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.ASSET_CLASS IS '분류 - STD/SMA0/SMA1/SMA2/NPA';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.BORROWER_EXPOSURE_INR IS '차주 총익스포저 - CRILC 기준(₹5 crore 이상) 판정';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.CRILC_RPT_YN IS 'CRILC 보고 대상';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.PROVISION_AMT IS '충당금';
COMMENT ON COLUMN TB_TF_ASSET_CLASS.INCOME_STOP_YN IS '이자인식 중단 - NPA';

-- 외화 어음 결정(Crystallisation) : 만기 후 미회수 외화 수출어음을 FEDAI 규칙에 따라 INR 채권으로 전환.
CREATE TABLE TB_TF_CRYSTAL (
